// Function node "enrich": validasi payload, tambahkan metadata
const nodeId = msg.topic.split('/')[1];   // soilnode/node01/telemetry -> node01
const p = msg.payload;

const valid =
  typeof p.soil_mv === 'number' && p.soil_mv > 0 && p.soil_mv < 3300 &&
  typeof p.soil_pct === 'number' && p.soil_pct >= 0 && p.soil_pct <= 100;

if (!valid) {
  node.warn('Payload tidak valid: ' + JSON.stringify(p));
  return null;
}

msg.payload = {
  node_id: nodeId,
  received_at: new Date().toISOString(),
  ...p,
  needs_water: p.state === 1,
  in_reliable_range: p.soil_pct <= 22   // sesuai README: andal sekitar 0-22 %
};
msg.topic = 'soilnode/' + nodeId + '/processed';
return msg;

// Function node "to_influx": format untuk node "influxdb out"
// msg.measurement + msg.payload = [fields, tags]
const p = msg.payload;

const fields = {
  soil_mv: p.soil_mv,
  soil_pct: p.soil_pct,
  light: p.light,
  state: p.state
};
// DHT bisa null saat belum terbaca: jangan kirim field kosong
if (typeof p.temp_c === 'number') fields.temp_c = p.temp_c;
if (typeof p.rh === 'number') fields.rh = p.rh;

msg.measurement = 'soil_node';
msg.payload = [fields, { node_id: p.node_id }];
return msg;
